import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Altezza di una torre.","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/i_trigonometria/ie/iebda.md","filePath":"lezioni/i_trigonometria/ie/iebda.md"}`),a={name:`lezioni/i_trigonometria/ie/iebda.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="altezza-di-una-torre" tabindex="-1">Altezza di una torre. <a class="header-anchor" href="#altezza-di-una-torre" aria-label="Permalink to “Altezza di una torre.”">​</a></h1><h2 id="piede-della-torre-sul-piano-dell-osservatore-ed-accessibile" tabindex="-1">Piede della torre sul piano dell&#39;osservatore ed accessibile <a class="header-anchor" href="#piede-della-torre-sul-piano-dell-osservatore-ed-accessibile" aria-label="Permalink to “Piede della torre sul piano dell&#39;osservatore ed accessibile”">​</a></h2><p>In questo caso il problema si presenta in modo piuttosto semplice.</p><p>Spostandoci dalla base <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mtext>A</mtext></mrow><annotation encoding="application/x-tex">\\text{A}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord text"><span class="mord">A</span></span></span></span></span> della torre ad un punto <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mtext>B</mtext></mrow><annotation encoding="application/x-tex">\\text{B}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord text"><span class="mord">B</span></span></span></span></span> calcoliamo la distanza <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mtext>AB</mtext></mrow><annotation encoding="application/x-tex">\\text{AB}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord text"><span class="mord">AB</span></span></span></span></span> e consideriamo il triangolo rettangolo <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mtext>ABC</mtext></mrow><annotation encoding="application/x-tex">\\text{ABC}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord text"><span class="mord">ABC</span></span></span></span></span>. Calcoliamo poi l&#39;angolo <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>α</mi></mrow><annotation encoding="application/x-tex">\\alpha</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0037em;">α</span></span></span></span> e possiamo risolvere il triangolo <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mtext>ABC</mtext></mrow><annotation encoding="application/x-tex">\\text{ABC}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord text"><span class="mord">ABC</span></span></span></span></span>.</p><p>Per la proprietà dei triangoli rettangoli ho:</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mstyle mathcolor="red"><mtext>BC</mtext><mo>=</mo><mtext>AB</mtext><mi>tan</mi><mo>⁡</mo><mi>α</mi></mstyle></mrow><annotation encoding="application/x-tex">\\textcolor{red}{\\text{BC} = \\text{AB} \\tan \\alpha} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord text" style="color:red;"><span class="mord" style="color:red;">BC</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel" style="color:red;">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord text" style="color:red;"><span class="mord" style="color:red;">AB</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop" style="color:red;"><span style="color:red;">t</span><span style="color:red;">a</span><span style="color:red;">n</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0037em;color:red;">α</span></span></span></span></span></p><p>Come volevamo.</p><blockquote><p><strong>Esercizio</strong> Supponiamo di spostarci dal punto <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mtext>B</mtext></mrow><annotation encoding="application/x-tex">\\text{B}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord text"><span class="mord">B</span></span></span></span></span> di <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>30</mn><mtext>\xA0m</mtext></mrow><annotation encoding="application/x-tex">30\\text{ m}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">30</span><span class="mord text"><span class="mord">\xA0m</span></span></span></span></span><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mtext>AB</mtext><mo>=</mo><mn>30</mn><mtext>\xA0m</mtext></mrow><annotation encoding="application/x-tex">\\text{AB} = 30\\text{ m}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord text"><span class="mord">AB</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">30</span><span class="mord text"><span class="mord">\xA0m</span></span></span></span></span> e che l&#39;angolo <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>α</mi></mrow><annotation encoding="application/x-tex">\\alpha</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0037em;">α</span></span></span></span> misuri <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mn>50</mn><mo>∘</mo></msup></mrow><annotation encoding="application/x-tex">50^\\circ</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6741em;"></span><span class="mord">5</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6741em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="katex-sizing reset-size6 size3 mtight"><span class="mbin mtight">∘</span></span></span></span></span></span></span></span></span></span></span> e quindi ho:</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mtext>BC</mtext><mo>=</mo><mtext>AB</mtext><mi>tan</mi><mo>⁡</mo><mi>α</mi><mo>=</mo><mn>30</mn><mtext>m</mtext><mo>⋅</mo><mi>tan</mi><mo>⁡</mo><msup><mn>50</mn><mo>∘</mo></msup><mo>=</mo><mn>30</mn><mtext>m</mtext><mo>⋅</mo><mn>1</mn><mo separator="true">,</mo><mn>192</mn><mo>=</mo><mn>35</mn><mo separator="true">,</mo><mn>76</mn><mtext>\xA0m</mtext></mrow><annotation encoding="application/x-tex">\\text{BC} = \\text{AB} \\tan \\alpha = 30\\text{m} \\cdot \\tan 50^\\circ = 30\\text{m} \\cdot 1,192 = 35,76\\text{ m} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord text"><span class="mord">BC</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord text"><span class="mord">AB</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop">tan</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0037em;">α</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">30</span><span class="mord text"><span class="mord">m</span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">⋅</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.7241em;"></span><span class="mop">tan</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">5</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.7241em;"><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="katex-sizing reset-size6 size3 mtight"><span class="mbin mtight">∘</span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">30</span><span class="mord text"><span class="mord">m</span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">⋅</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.8389em;vertical-align:-0.1944em;"></span><span class="mord">1</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">192</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.8389em;vertical-align:-0.1944em;"></span><span class="mord">35</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">76</span><span class="mord text"><span class="mord">\xA0m</span></span></span></span></span></span></p><p>Naturalmente possiamo approssimare ad una cifra decimale perché la nostra misura certamente non è esatta al centimetro: in queste misure un&#39;approssimazione al decimetro è un buon risultato. <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mtext>BC</mtext><mo>=</mo><mn>35</mn><mo separator="true">,</mo><mn>8</mn><mtext>\xA0m</mtext></mrow><annotation encoding="application/x-tex">\\text{BC} = 35,8\\text{ m}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord text"><span class="mord">BC</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.8389em;vertical-align:-0.1944em;"></span><span class="mord">35</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">8</span><span class="mord text"><span class="mord">\xA0m</span></span></span></span></span></p></blockquote>`,8)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};